import React, { useState } from 'react';
import { getAvailableSizes, getSizeLabel, getSizeDescription } from '../../utils/sizes';

const SizeSelector = ({ 
  product, 
  selectedSize, 
  onSizeChange, 
  availableSizes: productSizes,
  className = ''
}) => {
  const [showSizeGuide, setShowSizeGuide] = useState(false);
  
  const availableSizes = getAvailableSizes(product.category);
  const currentSizes = productSizes || product.sizes || [];

  const handleSizeSelect = (sizeType, size) => {
    const selectedSizeObj = {
      name: size.name,
      type: sizeType,
      stock: size.stock || 0,
      price: size.price || product.price
    };
    onSizeChange(selectedSizeObj);
  };

  const isSizeSelected = (sizeType, size) => {
    return selectedSize && 
           selectedSize.name === size.name && 
           selectedSize.type === sizeType;
  };

  const isSizeAvailable = (sizeType, size) => {
    const sizeObj = currentSizes.find(s => 
      s.name === size.name && s.type === sizeType
    );
    return sizeObj && sizeObj.stock > 0;
  };

  const getSizeStock = (sizeType, size) => {
    const sizeObj = currentSizes.find(s => 
      s.name === size.name && s.type === sizeType
    );
    return sizeObj ? sizeObj.stock : 0;
  };

  const renderSizeOption = (sizeType, size) => {
    const isSelected = isSizeSelected(sizeType, size);
    const isAvailable = isSizeAvailable(sizeType, size);
    const stock = getSizeStock(sizeType, size);

    return (
      <button
        key={`${sizeType}-${size.name}`}
        type="button"
        onClick={() => handleSizeSelect(sizeType, size)}
        disabled={!isAvailable}
        className={`
          size-option
          ${isSelected ? 'selected' : ''}
          ${!isAvailable ? 'unavailable' : ''}
          ${className}
        `}
        title={size.description}
      >
        <span className="size-name">{size.label || size.name}</span>
        {!isAvailable && (
          <span className="out-of-stock">Out of Stock</span>
        )}
        {isAvailable && stock <= 5 && (
          <span className="low-stock">Only {stock} left</span>
        )}
      </button>
    );
  };

  const renderSizeSection = (sizeType, sizes) => {
    if (!sizes || sizes.length === 0) return null;

    const sectionTitles = {
      standard: 'Standard Sizes',
      numeric: 'Numeric Sizes (Waist)',
      plus: 'Plus Sizes',
      kids: 'Kids Sizes',
      men: "Men's Shoes",
      women: "Women's Shoes",
      kids: "Kids' Shoes"
    };

    return (
      <div key={sizeType} className="size-section">
        <h4 className="size-section-title">{sectionTitles[sizeType]}</h4>
        <div className="size-options-grid">
          {sizes.map(size => renderSizeOption(sizeType, size))}
        </div>
      </div>
    );
  };

  return (
    <div className="size-selector">
      <div className="size-selector-header">
        <h3>Select Size</h3>
        <button
          type="button"
          className="size-guide-btn"
          onClick={() => setShowSizeGuide(!showSizeGuide)}
        >
          Size Guide
        </button>
      </div>

      {selectedSize && (
        <div className="selected-size-display">
          <span className="selected-size-label">
            Selected: {getSizeLabel(selectedSize.name, selectedSize.type)}
          </span>
          {getSizeDescription(selectedSize.name, selectedSize.type) && (
            <span className="selected-size-description">
              {getSizeDescription(selectedSize.name, selectedSize.type)}
            </span>
          )}
        </div>
      )}

      <div className="size-options-container">
        {Object.entries(availableSizes).map(([sizeType, sizes]) => 
          renderSizeSection(sizeType, sizes)
        )}
      </div>

      {showSizeGuide && (
        <div className="size-guide-modal">
          <div className="size-guide-content">
            <div className="size-guide-header">
              <h3>Size Guide</h3>
              <button
                type="button"
                className="close-btn"
                onClick={() => setShowSizeGuide(false)}
              >
                ×
              </button>
            </div>
            
            <div className="size-guide-body">
              {Object.entries(availableSizes).map(([sizeType, sizes]) => (
                <div key={sizeType} className="size-guide-section">
                  <h4>
                    {sizeType === 'standard' && 'Standard Sizes'}
                    {sizeType === 'numeric' && 'Numeric Sizes (Waist)'}
                    {sizeType === 'plus' && 'Plus Sizes'}
                    {sizeType === 'kids' && 'Kids Sizes'}
                    {sizeType === 'men' && "Men's Shoes"}
                    {sizeType === 'women' && "Women's Shoes"}
                  </h4>
                  <div className="size-guide-grid">
                    {sizes.map(size => (
                      <div key={size.name} className="size-guide-item">
                        <strong>{size.label || size.name}</strong>
                        <small>{size.description}</small>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default SizeSelector;
